import pytest
from unittest.mock import MagicMock, patch, call
import reconcile.sentry_config as sentry_config
import logging

logging.basicConfig(level=logging.INFO)


class TestSentryProjectOwnershipFix:
    """Test the fix for Sentry project ownership reconciliation."""

    def setup_method(self):
        self.mock_client = MagicMock()
        self.mock_client.host = "https://sentry.example.com"
        # Mock methods that are called during reconciliation
        self.mock_client.get_project_alert_rules.return_value = []
        self.mock_client.get_project.return_value = {
            'slug': 'project-x',
            'subjectPrefix': '',
            'platform': ''
        }
        self.mock_client.required_project_fields.return_value = {}
        self.mock_client.optional_project_fields.return_value = {}
        self.mock_client.validate_project_options.return_value = None
        self.reconciler = sentry_config.SentryReconciler(
            self.mock_client, dry_run=False
        )

    def _create_state(self, teams=None, users=None, projects=None, roles=None):
        """Helper to create a SentryState instance."""
        state = sentry_config.SentryState()
        if teams is not None:
            state.init_teams(teams)
        if users is not None:
            state.init_users(users)
        if projects is not None:
            state.init_projects(projects)
        if roles is not None:
            state.init_roles(roles)
        return state

    def test_single_owner_matches_desired(self):
        """Project already has the correct single owner -> no changes."""
        current = self._create_state(
            teams=['team-a'],
            projects={'team-a': [{'name': 'project-x'}]}
        )
        desired = self._create_state(
            teams=['team-a'],
            projects={'team-a': [{'name': 'project-x'}]}
        )
        self.mock_client.get_project_owners.return_value = [
            {'slug': 'team-a'}
        ]
        self.reconciler.reconcile(current, desired)
        self.mock_client.delete_project_owner.assert_not_called()
        self.mock_client.add_project_owner.assert_not_called()

    def test_single_owner_different_from_desired(self):
        """Project has a single owner that is not the desired team.
        Expect add_project_owner (but no delete)."""
        current = self._create_state(
            teams=['team-b'],
            projects={'team-b': [{'name': 'project-x'}]}
        )
        desired = self._create_state(
            teams=['team-a'],
            projects={'team-a': [{'name': 'project-x'}]}
        )
        self.mock_client.get_project_owners.return_value = [
            {'slug': 'team-b'}
        ]
        self.reconciler.reconcile(current, desired)
        self.mock_client.delete_project_owner.assert_not_called()
        self.mock_client.add_project_owner.assert_called_once_with(
            'project-x', 'team-a'
        )

    def test_multiple_owners_desired_present_first(self):
        """Project has multiple owners, desired team is first.
        Expected: delete extra owners."""
        current = self._create_state(
            teams=['team-a', 'team-b', 'team-c'],
            projects={
                'team-a': [{'name': 'project-x'}],
                'team-b': [{'name': 'project-x'}],
                'team-c': [{'name': 'project-x'}]
            }
        )
        desired = self._create_state(
            teams=['team-a'],
            projects={'team-a': [{'name': 'project-x'}]}
        )
        self.mock_client.get_project_owners.return_value = [
            {'slug': 'team-a'},
            {'slug': 'team-b'},
            {'slug': 'team-c'}
        ]
        self.reconciler.reconcile(current, desired)
        expected_delete_calls = [
            call('project-x', 'team-b'),
            call('project-x', 'team-c')
        ]
        self.mock_client.delete_project_owner.assert_has_calls(
            expected_delete_calls, any_order=True
        )
        assert self.mock_client.delete_project_owner.call_count == 2
        self.mock_client.add_project_owner.assert_not_called()

    def test_multiple_owners_desired_present_not_first(self):
        """Project has multiple owners, desired team is not first.
        Old bug: would delete desired team because comparison used first owner.
        New fix: should keep desired team and delete others."""
        current = self._create_state(
            teams=['team-b', 'team-a', 'team-c'],
            projects={
                'team-b': [{'name': 'project-x'}],
                'team-a': [{'name': 'project-x'}],
                'team-c': [{'name': 'project-x'}]
            }
        )
        desired = self._create_state(
            teams=['team-a'],
            projects={'team-a': [{'name': 'project-x'}]}
        )
        self.mock_client.get_project_owners.return_value = [
            {'slug': 'team-b'},
            {'slug': 'team-a'},
            {'slug': 'team-c'}
        ]
        self.reconciler.reconcile(current, desired)
        # team-b and team-c should be deleted, team-a kept
        expected_delete_calls = [
            call('project-x', 'team-b'),
            call('project-x', 'team-c')
        ]
        self.mock_client.delete_project_owner.assert_has_calls(
            expected_delete_calls, any_order=True
        )
        assert self.mock_client.delete_project_owner.call_count == 2
        self.mock_client.add_project_owner.assert_not_called()

    def test_multiple_owners_desired_absent(self):
        """Project has multiple owners, desired team not present.
        Expected: delete all existing owners, add desired team."""
        current = self._create_state(
            teams=['team-b', 'team-c'],
            projects={
                'team-b': [{'name': 'project-x'}],
                'team-c': [{'name': 'project-x'}]
            }
        )
        desired = self._create_state(
            teams=['team-a'],
            projects={'team-a': [{'name': 'project-x'}]}
        )
        self.mock_client.get_project_owners.return_value = [
            {'slug': 'team-b'},
            {'slug': 'team-c'}
        ]
        self.reconciler.reconcile(current, desired)
        expected_delete_calls = [
            call('project-x', 'team-b'),
            call('project-x', 'team-c')
        ]
        self.mock_client.delete_project_owner.assert_has_calls(
            expected_delete_calls, any_order=True
        )
        assert self.mock_client.delete_project_owner.call_count == 2
        self.mock_client.add_project_owner.assert_called_once_with(
            'project-x', 'team-a'
        )


if __name__ == "__main__":
    pytest.main(["-v", __file__])

import sys
import pytest
from pathlib import Path
import configparser

def test_python_requires_updated():
    """Check that python_requires is >=3.7, not >=3.6.1."""
    config = configparser.ConfigParser()
    config.read("setup.cfg")
    requires = config.get("options", "python_requires", fallback="")
    assert requires == ">=3.7", f"Expected python_requires '>=3.7', got '{requires}'"

def test_future_annotations_in_main():
    """Check that __main__.py contains from __future__ import annotations."""
    main_file = Path("add_trailing_comma/__main__.py")
    content = main_file.read_text()
    assert "from __future__ import annotations" in content, \
        "__main__.py missing future annotations import"

def test_precommit_config_pyupgrade_py37_plus():
    """Check that .pre-commit-config.yaml pyupgrade uses --py37-plus."""
    config_file = Path(".pre-commit-config.yaml")
    content = config_file.read_text()
    # Find the pyupgrade repo section
    lines = content.splitlines()
    in_pyupgrade = False
    for i, line in enumerate(lines):
        if line.strip().startswith("- repo: https://github.com/asottile/pyupgrade"):
            in_pyupgrade = True
        if in_pyupgrade and line.strip().startswith("args:"):
            # Check next line(s) for --py37-plus
            # Usually it's a list on the same line or next lines
            # We'll just check the next few lines
            for j in range(i, min(i+5, len(lines))):
                if "--py37-plus" in lines[j]:
                    break
            else:
                pytest.fail("--py37-plus not found in pyupgrade args")
            # Also ensure --py36-plus is not present in pyupgrade args
            for j in range(i, min(i+5, len(lines))):
                if "--py36-plus" in lines[j]:
                    pytest.fail("--py36-plus still present in pyupgrade args")
            break
    else:
        pytest.fail("Could not find pyupgrade repo in .pre-commit-config.yaml")

def test_precommit_config_reorder_imports_py37_plus():
    """Check that reorder-python-imports uses --py37-plus and --add-import."""
    config_file = Path(".pre-commit-config.yaml")
    content = config_file.read_text()
    lines = content.splitlines()
    in_reorder = False
    for i, line in enumerate(lines):
        if line.strip().startswith("- repo: https://github.com/asottile/reorder_python_imports"):
            in_reorder = True
        if in_reorder and line.strip().startswith("args:"):
            # Check for --py37-plus and --add-import
            found_py37 = False
            found_add_import = False
            for j in range(i, min(i+5, len(lines))):
                if "--py37-plus" in lines[j]:
                    found_py37 = True
                if "--add-import" in lines[j]:
                    found_add_import = True
            assert found_py37, "--py37-plus not found in reorder-python-imports args"
            assert found_add_import, "--add-import not found in reorder-python-imports args"
            break
    else:
        pytest.fail("Could not find reorder_python_imports repo in .pre-commit-config.yaml")

def test_tox_envlist_no_py36():
    """Check that tox.ini envlist does not include py36."""
    tox_file = Path("tox.ini")
    content = tox_file.read_text()
    lines = content.splitlines()
    for line in lines:
        if line.strip().startswith("envlist ="):
            # py36 should not be in the list
            assert "py36" not in line, \
                f"tox envlist still includes py36: {line}"
            break
    else:
        pytest.fail("Could not find envlist line in tox.ini")

if __name__ == "__main__":
    sys.exit(pytest.main(["-v", __file__]))

import pytest
import json
import sys
from unittest.mock import patch, MagicMock
import reconcile.github_org
from reconcile.aggregated_list import AggregatedList

def test_bot_schema_new_version():
    """Test that bot with schema 'access/bot-1.yml' is correctly handled."""
    # Mock config
    with patch('reconcile.github_org.get_config') as mock_get_config:
        mock_get_config.return_value = {
            'github': {
                'test-org': {'token': 'fake-token'}
            }
        }
        # Mock GQL query response with new schema bot
        mock_gqlapi = MagicMock()
        mock_gqlapi.query.return_value = json.dumps({
            'data': {
                'role': [
                    {
                        'name': 'role1',
                        'members': [
                            {
                                'schema': 'access/bot-1.yml',
                                'github_username_optional': 'bot-user'
                            }
                        ],
                        'permissions': [
                            {
                                'service': 'github-org',
                                'org': 'test-org'
                            }
                        ]
                    }
                ]
            }
        })
        with patch('reconcile.github_org.gql.get_api', return_value=mock_gqlapi):
            # Mock fetch_current_state to return a state with matching org
            with patch('reconcile.github_org.fetch_current_state') as mock_fetch_current:
                # Create a real AggregatedList for current state
                current_state = AggregatedList()
                current_state.add(
                    {'service': 'github-org', 'org': 'test-org'},
                    ['bot-user']
                )
                mock_fetch_current.return_value = current_state
                # Run with dry_run (will call sys.exit)
                with pytest.raises(SystemExit) as excinfo:
                    reconcile.github_org.run(dry_run=True)
                # Ensure exit code is 0
                assert excinfo.value.code == 0

def test_fragment_names_new_version():
    """Test that GraphQL query uses new fragment names (Bot_v1, PermissionGithubOrg_v1)."""
    captured_query = None
    def capture_query(query, variables=None):
        nonlocal captured_query
        captured_query = query
        # Return empty result
        return json.dumps({'data': {'role': []}})
    mock_gqlapi = MagicMock()
    mock_gqlapi.query.side_effect = capture_query
    with patch('reconcile.github_org.gql.get_api', return_value=mock_gqlapi):
        with patch('reconcile.github_org.get_config') as mock_get_config:
            mock_get_config.return_value = {'github': {}}
            with patch('reconcile.github_org.fetch_current_state') as mock_fetch_current:
                mock_fetch_current.return_value = AggregatedList()
                # This will call fetch_desired_state which uses the query
                reconcile.github_org.fetch_desired_state()
    # Assert that the query contains new fragment names
    assert '...on Bot_v1' in captured_query, f"Expected '...on Bot_v1' in query, got: {captured_query}"
    assert '...on PermissionGithubOrg_v1' in captured_query, f"Expected '...on PermissionGithubOrg_v1' in query, got: {captured_query}"
    # Ensure old fragment names are NOT present (excluding substrings)
    # Check that there is no fragment '...on Bot' (with space after Bot) that is not followed by _v1
    import re
    # Find all occurrences of '...on Bot' (with any whitespace) and ensure they are followed by _v1
    # We'll just check that there is no '...on Bot' where the next characters are not '_v1'
    # For simplicity, we can check that '...on Bot' is not followed by whitespace or newline (but it's okay if it's part of Bot_v1)
    # Actually, the pattern '...on Bot' appears only as part of '...on Bot_v1' because the fragment name is Bot_v1.
    # So we can assert that there is no '...on Bot' followed by a space or newline (i.e., not followed by '_v1').
    # Let's use regex: r'\.\.\.on Bot(\s|$)'
    if re.search(r'\.\.\.on Bot(\s|$)', captured_query):
        raise AssertionError("Old fragment '...on Bot' found in query")
    if re.search(r'\.\.\.on PermissionGithubOrg(\s|$)', captured_query):
        raise AssertionError("Old fragment '...on PermissionGithubOrg' found in query")

if __name__ == "__main__":
    sys.exit(pytest.main(["-v", __file__]))

import sys
import pytest
from unittest.mock import Mock, patch, call
import reconcile.openshift_groups as openshift_groups

def test_fetch_desired_state_basic():
    """Test that fetch_desired_state returns correct entries for valid access."""
    mock_gql = Mock()
    mock_gql.query.return_value = {
        'roles': [
            {
                'users': [{'github_username': 'user1'}],
                'access': [
                    {
                        'cluster': {'name': 'cluster1'},
                        'group': 'group1'
                    }
                ]
            }
        ]
    }
    mock_oc_map = Mock()
    mock_oc_map.clusters.return_value = {'cluster1'}

    with patch('reconcile.openshift_groups.gql.get_api', return_value=mock_gql):
        result = openshift_groups.fetch_desired_state(mock_oc_map)

    assert len(result) == 1
    assert result[0] == {
        'cluster': 'cluster1',
        'group': 'group1',
        'user': 'user1'
