def test_run_integration_add_user():
    """Test the run function with mocks to verify integration works."""
    # Mock gql.get_api for both fetch_current_state and fetch_desired_state
    mock_gql = Mock()
    # For fetch_current_state: CLUSTERS_QUERY returns clusters with managedGroups
    mock_gql.query.side_effect = [
        {'clusters': [
            {'name': 'cluster1', 'managedGroups': ['group1']}
        ]},
        {'roles': [
            {
                'users': [{'github_username': 'user1'}],
                'access': [
                    {
                        'cluster': {'name': 'cluster1'},
                        'group': 'group1'
                    }
                ]
            }
        ]},
        {'clusters': [
            {'name': 'cluster1', 'managedGroups': ['group1']}
        ]}
    ]
    # Mock OC_Map
    mock_oc_map = Mock()
    mock_oc_map.clusters.return_value = {'cluster1'}
    mock_oc_map.get.return_value = Mock()
    mock_oc_map.cleanup = Mock()
    # Mock threaded.run for fetch_current_state's get_cluster_state
    mock_threaded_run = Mock(return_value=[[
        {'cluster': 'cluster1', 'group': 'group1', 'user': 'existing_user'}
    ]])

    with patch('reconcile.openshift_groups.gql.get_api', return_value=mock_gql), \
         patch('reconcile.openshift_groups.OC_Map', return_value=mock_oc_map), \
         patch('reconcile.openshift_groups.threaded.run', mock_threaded_run), \
         patch('reconcile.openshift_groups.logging.info') as mock_logging:
        # Call run with dry_run=True to avoid actual actions
        openshift_groups.run(dry_run=True, thread_pool_size=1)

    # Verify that oc_map.cleanup was called (via defer)
    mock_oc_map.cleanup.assert_called_once()
    # Verify logging calls (optional)
    # Expect diff for adding user1 to group1 (since existing_user is already there)
    # The diff should include add_user_to_group for user1
    # We can capture the diff passed to logging.info
    # Instead, we can assert that logging.info was called with certain values
    # Let's just ensure it was called (not empty)
    assert mock_logging.called

