import pytest
import requests
from unittest.mock import MagicMock, patch, call
from reconcile.dashdotdb_cso import DashdotdbCSO

@pytest.fixture
def mock_dependencies():
    """
    Mock the external dependencies of DashdotdbCSO.__init__
    """
    with patch('reconcile.dashdotdb_cso.queries.get_app_interface_settings') as mock_settings, \
         patch('reconcile.dashdotdb_cso.secret_reader.read_all') as mock_read_all:
        # Mock settings
        mock_settings.return_value = {}
        # Mock secret content
        mock_read_all.return_value = {
            'url': 'http://example.com',
            'username': 'user',
            'password': 'pass'
        }
        yield mock_settings, mock_read_all

def test_post_single_item(mock_dependencies):
    """
    After fix: _post should call requests.post for each item in items.
    Before fix: _post would call requests.post once with the entire list.
    """
    with patch('reconcile.dashdotdb_cso.requests.post') as mock_post:
        mock_response = MagicMock()
        mock_response.raise_for_status = MagicMock()
        mock_post.return_value = mock_response

        dash = DashdotdbCSO(dry_run=False, thread_pool_size=1)
        # Simulate manifest with a single item
        manifest = {
            'cluster': 'test-cluster',
            'data': {
                'items': [
                    {'kind': 'imagemanifestvuln', 'metadata': {'name': 'vuln1'}}
                ]
            }
        }
        dash._post(manifest)

        # After fix: expect one call with the item
        assert mock_post.call_count == 1
        # Check that the json argument is the single item, not the whole data
        call_args = mock_post.call_args
        # call_args is (args, kwargs). args is empty because all arguments are keyword-based.
        kwargs = call_args[1]
        json_sent = kwargs['json']
        assert json_sent == {'kind': 'imagemanifestvuln', 'metadata': {'name': 'vuln1'}}
        # Ensure endpoint includes cluster
        assert kwargs['url'] == f'{dash.dashdotdb_url}/api/v1/imagemanifestvuln/test-cluster'

def test_post_multiple_items(mock_dependencies):
    """
    After fix: _post should call requests.post for each item.
    Before fix: _post would call requests.post once with the entire list.
    """
    with patch('reconcile.dashdotdb_cso.requests.post') as mock_post:
        mock_response = MagicMock()
        mock_response.raise_for_status = MagicMock()
        mock_post.return_value = mock_response

        dash = DashdotdbCSO(dry_run=False, thread_pool_size=1)
