import pytest
from unittest.mock import MagicMock, patch
import reconcile.utils.terraform_client as tfclient

def create_mocked_client():
    """Create a TerraformClient with mocked init methods."""
    with patch.object(tfclient.TerraformClient, 'init_specs'), \
         patch.object(tfclient.TerraformClient, 'init_outputs'):
        client = tfclient.TerraformClient(
            integration='test',
            integration_version='v1',
            integration_prefix='test',
            accounts=[{'name': 'test-account'}],
            working_dirs={'test-account': '/tmp'},
            thread_pool_size=1,
            init_users=False
        )
    # Ensure accounts dict is set correctly
    client.accounts = {'test-account': {}}
    client.outputs = {'test-account': {'existing_output': {'value': 'old'}}}
    client.specs = []  # not used in log_plan_diff
    return client

def test_log_plan_diff_deleted_output():
    """Test that deleted outputs are detected and should_apply set to True."""
    client = create_mocked_client()
    # Mock terraform_show to return prior_state with output but empty output_changes
    mock_show = {
        'format_version': '0.1',
        'prior_state': {
            'values': {
                'outputs': {
                    'existing_output': {'value': 'old'},
                    'deleted_output': {'value': 'to_delete'}
                }
            }
        },
        'output_changes': {}
    }
    with patch.object(client, 'terraform_show', return_value=mock_show):
        client.log_plan_diff('test-account', MagicMock(), enable_deletion=False)
    # After fix, should_apply should be True because deleted_output is missing from output_changes
    assert client.should_apply == True

def test_log_plan_diff_updated_output():
    """Test that updated outputs are detected (existing behavior)."""
    client = create_mocked_client()
    mock_show = {
        'format_version': '0.1',
        'prior_state': {'values': {'outputs': {}}},
        'output_changes': {
            'existing_output': {'after': 'new'}
        }
    }
    with patch.object(client, 'terraform_show', return_value=mock_show):
        client.log_plan_diff('test-account', MagicMock(), enable_deletion=False)
    assert client.should_apply == True

def test_log_plan_diff_no_changes():
    """Test that no changes leaves should_apply False."""
    client = create_mocked_client()
    mock_show = {
        'format_version': '0.1',
        'prior_state': {'values': {'outputs': {'existing_output': {'value': 'old'}}}},
        'output_changes': {'existing_output': {'after': 'old'}}
    }
    with patch.object(client, 'terraform_show', return_value=mock_show):
        client.log_plan_diff('test-account', MagicMock(), enable_deletion=False)
    assert client.should_apply == False

