from reconcile.openshift_acme import construct_resources

def test_role_without_acme_secrets():
    """When acmeSecrets is not provided, resourceNames should be absent."""
    namespace = {
        "name": "test-ns",
        "cluster": {"name": "test-cluster"},
        "openshiftAcme": {
            "config": {"image": "test-image"},
            "overrides": {}
        }
    }
    namespaces = [namespace]
    result = construct_resources(namespaces)
    assert len(result) == 1
    resources = result[0]["resources"]
    # Find the Role resource
    role = None
    for r in resources:
        if r.kind == "Role":
            role = r
            break
    assert role is not None
    # Check the rules for secrets
    for rule in role.body["rules"]:
        if "secrets" in rule.get("resources", []):
            # resourceNames should not be present
            assert "resourceNames" not in rule
            break
    else:
        pytest.fail("No secrets rule found in Role")

