from reconcile.openshift_rolebindings import fetch_desired_state

def compute_shard(value, shards, shard_id):
    """Helper to compute if value belongs to shard_id."""
    if shards == 1:
        return True
    value_md5 = hashlib.md5(value.encode())
    value_hex = value_md5.hexdigest()
    value_int = int(value_hex, base=16)
    return value_int % shards == shard_id

def test_sharding_disabled():
    """
    When SHARDS=1, all permissions should be processed regardless of SHARD_ID.
    """
    with patch('utils.sharding.SHARDS', 1), patch('utils.sharding.SHARD_ID', 0):
        # Mock gql.get_api().query to return a single role with permissions
