import pytest
import sys
import ast
import os
import inspect

def test_plot_repr_call_has_references():
    """
    Check that the call to plot_repr in predictive_finder.py includes the references argument.
    """
    file_path = os.path.join(os.path.dirname(__file__), 'preliz', 'predictive', 'predictive_finder.py')
    with open(file_path, 'r') as f:
        source = f.read()
    tree = ast.parse(source)
    # Find the MatchDistribution class
    for node in ast.walk(tree):
        if isinstance(node, ast.ClassDef) and node.name == 'MatchDistribution':
            # Find its __call__ method
            for item in node.body:
                if isinstance(item, ast.FunctionDef) and item.name == '__call__':
                    # Look for call to plot_repr
                    for stmt in ast.walk(item):
                        if isinstance(stmt, ast.Call):
                            # Check if the function being called is plot_repr
                            if isinstance(stmt.func, ast.Name) and stmt.func.id == 'plot_repr':
                                # Check number of positional arguments
                                # Expected: self.pp_samples, kind_plot, None, self.draws, self.ax
                                if len(stmt.args) == 5:
                                    # Check that the third argument is None (ast.Constant)
                                    if isinstance(stmt.args[2], ast.Constant) and stmt.args[2].value is None:
                                        return  # Test passes
                                    else:
                                        pytest.fail("Third argument to plot_repr is not None")
                                else:
                                    pytest.fail(f"plot_repr called with {len(stmt.args)} arguments, expected 5")
    pytest.fail("Could not find call to plot_repr in MatchDistribution.__call__")

def test_plot_repr_signature():
    """
    Check that plot_repr function signature includes references parameter.
    """
    from preliz.internal.plot_helper import plot_repr
    sig = inspect.signature(plot_repr)
    params = list(sig.parameters.keys())
    assert 'references' in params, f"references not in signature: {params}"
    # Check that references is the third parameter (after results, kind_plot)
    expected_order = ['results', 'kind_plot', 'references', 'iterations', 'ax']
    # Allow extra parameters? The signature may have self if it's a method? Actually it's a function.
    # We'll just check that references appears before iterations.
