def test_target_namespace_zone_populates_records():
    """
    When a record has _target_namespace_zone, the records field should be
    populated with NS records from the referenced zone.
    """
    zones = [
        {
            "name": "example.com",
            "account": {"name": "aws-account"},
            "records": [
                {
                    "name": "subdomain.example.com",
                    "type": "NS",
                    "_target_namespace_zone": {
                        "namespace": {
                            "terraformResources": [
                                {
                                    "provider": "route53-zone",
                                    "name": "target-zone",
                                    "account": "aws-account",
                                    "region": "us-east-1",
                                }
                            ]
                        },
                        "name": "target-zone",
                    },
                }
            ],
        }
    ]
    all_accounts = [
        {
            "name": "aws-account",
            "automationToken": "some-token",
            "resourcesDefaultRegion": "us-east-1",
        }
    ]
    settings = {}

    # Mock AWSApi.get_route53_zone_ns_records to return dummy NS records
    with patch("reconcile.terraform_aws_route53.AWSApi") as MockAWSApi:
        mock_aws_api = MockAWSApi.return_value
        mock_aws_api.get_route53_zone_ns_records.return_value = [
            "ns1.example.com",
            "ns2.example.com",
        ]
        desired_state = build_desired_state(zones, all_accounts, settings)

    # Expect one zone in desired state
    assert len(desired_state) == 1
    zone_state = desired_state[0]
    assert zone_state["name"] == "example.com"
    assert zone_state["account_name"] == "aws-account"
    records = zone_state["records"]
    assert len(records) == 1
    record = records[0]
    assert record["name"] == "subdomain.example.com"
    assert record["type"] == "NS"
    assert record["records"] == ["ns1.example.com", "ns2.example.com"]
    # Ensure _target_namespace_zone is popped
    assert "_target_namespace_zone" not in record


