        # Mock dnsutils.get_a_records for _target_cluster if needed (not used for CNAME)
        with patch("reconcile.terraform_aws_route53.dnsutils") as mock_dns:
            mock_dns.get_a_records.return_value = []  # not used
            desired_state = build_desired_state(zones, all_accounts, settings)

