def test_role_has_no_resource_names_even_with_acme_secrets():
    """
    Even if acmeSecrets is provided, the Role should NOT have resourceNames.
    This test will fail on the parent commit because resourceNames will be present.
    """
    namespace = {
        "name": "test-namespace",
        "openshiftAcme": {
            "config": {
                "image": "quay.io/openshift-acme/image:latest",
                "overrides": {}
            },
            # acmeSecrets is ignored in current code, but parent code would use it.
            "acmeSecrets": ["secret1", "secret2"]
        }
    }
    namespaces = [namespace]
    result = list(construct_resources(namespaces))
    assert len(result) == 1
    ns = result[0]
    resources = ns["resources"]
    # Find the Role resource
    role = None
    for r in resources:
        if r.kind == "Role":
            role = r
            break
    assert role is not None
    # Check rules for secrets
    rules = role.body.get("rules", [])
    secret_rule = None
    for rule in rules:
        if "secrets" in rule.get("resources", []):
            secret_rule = rule
            break
    assert secret_rule is not None
    # Ensure resourceNames is not present
    assert "resourceNames" not in secret_rule

