import pytest
import yaml
import os

def load_template():
    """Load and parse the OpenShift template YAML."""
    template_path = os.path.join(
        os.path.dirname(__file__), 'openshift/qontract-reconcile.yaml'
    )
    with open(template_path, 'r') as f:
        return yaml.safe_load(f)

def find_deployment(template, name):
    """Find a Deployment object by name in the template objects list."""
    for obj in template.get('objects', []):
        if obj.get('kind') == 'Deployment' and obj.get('metadata', {}).get('name') == name:
            return obj
    return None

def test_openshift_performance_parameters_deployment_exists():
    """Check that the openshift-performance-parameters deployment is present."""
    template = load_template()
    deployment = find_deployment(
        template, 'qontract-reconcile-openshift-performance-parameters'
    )
    assert deployment is not None, (
        'Deployment qontract-reconcile-openshift-performance-parameters not found in template'
    )

def test_openshift_performance_parameters_integration_name():
    """Check that the integration name environment variable is set correctly."""
    template = load_template()
    deployment = find_deployment(
        template, 'qontract-reconcile-openshift-performance-parameters'
    )
    # If deployment is missing, the previous test will have failed, but we can still skip.
    if deployment is None:
        pytest.skip('Deployment not found')
    containers = deployment['spec']['template']['spec']['containers']
    int_container = next((c for c in containers if c['name'] == 'int'), None)
    assert int_container is not None, 'Container named "int" not found'
    env_vars = {e['name']: e.get('value', '') for e in int_container.get('env', [])}
    assert env_vars.get('INTEGRATION_NAME') == 'openshift-performance-parameters', (
        f'INTEGRATION_NAME expected openshift-performance-parameters, got {env_vars.get("INTEGRATION_NAME")}'
    )

def test_openshift_performance_parameters_extra_args():
    """Check that the integration extra args include --no-use-jump-host."""
    template = load_template()
    deployment = find_deployment(
        template, 'qontract-reconcile-openshift-performance-parameters'
    )
    if deployment is None:
        pytest.skip('Deployment not found')
    containers = deployment['spec']['template']['spec']['containers']
    int_container = next((c for c in containers if c['name'] == 'int'), None)
    assert int_container is not None, 'Container named "int" not found'
    env_vars = {e['name']: e.get('value', '') for e in int_container.get('env', [])}
    extra_args = env_vars.get('INTEGRATION_EXTRA_ARGS', '')
    assert '--no-use-jump-host' in extra_args, (
        f'INTEGRATION_EXTRA_ARGS should contain --no-use-jump-host, got {extra_args}'
    )

