import pytest
from unittest.mock import patch, MagicMock
import reconcile.aws_support_cases_sos as sos

def _mock_aws(users_keys, support_cases):
    """Return a mocked AWSApi instance."""
    mock_aws = MagicMock()
    mock_aws.get_users_keys.return_value = users_keys
    mock_aws.get_support_cases.return_value = support_cases
    return mock_aws

def _mock_accounts(accounts_data):
    """Return mocked accounts list."""
    return [
        {'name': name, 'deleteKeys': delete_keys, 'premiumSupport': True}
        for name, delete_keys in accounts_data.items()
    ]

def _run_with_mocks(accounts_data, users_keys, support_cases, enable_deletion=True):
    """Run sos.run with mocked dependencies."""
    with patch('reconcile.aws_support_cases_sos.queries.get_aws_accounts',
               return_value=_mock_accounts(accounts_data)), \
         patch('reconcile.aws_support_cases_sos.queries.get_app_interface_settings',
               return_value={}), \
         patch('reconcile.aws_support_cases_sos.AWSApi') as MockAWSApi:
        mock_aws = _mock_aws(users_keys, support_cases)
        MockAWSApi.return_value = mock_aws
        captured_keys = []
        def mock_act(dry_run, gitlab_project_id, accounts, keys_to_delete):
            captured_keys.extend(keys_to_delete)
        with patch('reconcile.aws_support_cases_sos.act', side_effect=mock_act):
            sos.run(dry_run=True, enable_deletion=enable_deletion)
        return captured_keys

def test_key_detection_with_nested_user_keys():
    """
    Test that keys nested under users in existing_keys are detected.
    Old bug: key in existing_keys[account][user] but not a username.
    """
    accounts_data = {'test-account': []}
    users_keys = {'test-account': {'some-user': ['AKIAEXAMPLE']}}
    support_cases = {
        'test-account': [
            {
                'recentCommunications': {
                    'communications': [
                        {'body': 'We have become aware that the AWS Access Key AKIAEXAMPLE is compromised'}
                    ]
                }
            }
        ]
    }
    captured = _run_with_mocks(accounts_data, users_keys, support_cases)
    assert len(captured) == 1
    assert captured[0]['account'] == 'test-account'
    assert captured[0]['key'] == 'AKIAEXAMPLE'

def test_key_already_in_deleted_keys():
    """
    Key that is already listed in deleteKeys should be excluded.
    """
    accounts_data = {'test-account': ['AKIAEXAMPLE']}
    users_keys = {'test-account': {'user': ['AKIAEXAMPLE']}}
    support_cases = {
        'test-account': [
            {
                'recentCommunications': {
                    'communications': [
                        {'body': 'We have become aware that the AWS Access Key AKIAEXAMPLE is compromised'}
                    ]
                }
            }
        ]
