import sys
import unittest
import pytest
from test.helper import TestHelper

class AdvancedRewriteBugTest(unittest.TestCase, TestHelper):
    def setUp(self):
        self.setup_beets()

    def tearDown(self):
        self.unload_plugins()
        self.teardown_beets()

    def test_advanced_syntax_none_replacement_string(self):
        """Advanced syntax: replacement string 'None' should not set field to None."""
        self.config['advancedrewrite'] = [
            {
                "match": "artist:Radiohead",
                "replacements": {
                    "genre": "None",  # string literal
                },
            },
        ]
        self.load_plugins('advancedrewrite')
        item = self.add_item(artist='Radiohead', genre='Alternative')
        # The plugin should set genre to the string 'None', not None.
        self.assertEqual(item.genre, 'None')
        self.assertIsNotNone(item.genre)

    def test_advanced_syntax_expression_that_would_evaluate_to_none(self):
        """Advanced syntax: expression that would evaluate to None should not set field to None."""
        self.config['advancedrewrite'] = [
            {
                "match": "artist:Radiohead",
                "replacements": {
                    "genre": "'Rock' if artist == 'Beatles' else None",
                },
