class Environ:
    """Context manager to set environment variables."""
    def __init__(self, **kwargs):
        self.old = {}
        self.new = kwargs

    def __enter__(self):
        for key, value in self.new.items():
            if key in os.environ:
                self.old[key] = os.environ[key]
            os.environ[key] = value
        return self

    def __exit__(self, *args):
        for key in self.new:
            if key in self.old:
                os.environ[key] = self.old[key]
            else:
                os.environ.pop(key, None)


