def create_token(issuer, audience, key_id, private_key):
    signer = atlassian_jwt_auth.create_signer(
        issuer, key_id, private_key
    )
    return signer.generate_jwt(audience)


def get_flask_app():
    """Create a Flask app with a protected endpoint."""
    # Use a dummy module name that doesn't conflict with pytest's assertion rewrite
    app = Flask('test_flask_app')
    app.config.update({
        'ASAP_VALID_AUDIENCE': 'my-app',
        'ASAP_VALID_ISSUERS': ('trusted-issuer',),
        'ASAP_PUBLICKEY_REPOSITORY': None
    })

    @app.route("/protected")
    @requires_asap
    def protected():
        return "OK"

    return app


class FlaskInvalidIssuerTests(utils.RS256KeyTestMixin, unittest.TestCase):
    """Test Flask requires_asap decorator returns 403 for invalid issuer."""

    def setUp(self):
        self._private_key_pem = self.get_new_private_key_in_pem_format()
        self._public_key_pem = utils.get_public_key_pem_for_private_key_pem(
            self._private_key_pem
        )

        self.app = get_flask_app()
        self.client = self.app.test_client()

        # Configure retriever to know public key for 'untrusted-issuer'
        retriever_cls = get_static_retriever_class({
            'untrusted-issuer/key01': self._public_key_pem
        })
        self.app.config['ASAP_KEY_RETRIEVER_CLASS'] = retriever_cls

    def test_invalid_issuer_returns_403(self):
        """Invalid token issuer should return 403 Forbidden, not 401."""
        signer = atlassian_jwt_auth.create_signer(
            'untrusted-issuer', 'untrusted-issuer/key01', self._private_key_pem
        )
        token = signer.generate_jwt('my-app')
        # token is bytes, decode to string
        token_str = token.decode('utf-8')

        response = self.client.get('/protected', headers={
            'Authorization': 'Bearer ' + token_str
        })

        # This should be 403 after fix, 401 before fix
        self.assertEqual(response.status_code, 403)

    def test_invalid_issuer_message_starts_with_forbidden(self):
        """Error message should start with 'Forbidden:' not 'Unauthorized:'."""
        signer = atlassian_jwt_auth.create_signer(
            'untrusted-issuer', 'untrusted-issuer/key01', self._private_key_pem
        )
        token = signer.generate_jwt('my-app')
        token_str = token.decode('utf-8')

        response = self.client.get('/protected', headers={
            'Authorization': 'Bearer ' + token_str
        })

        response_text = response.get_data(as_text=True)
        self.assertTrue(response_text.startswith('Forbidden: Invalid token issuer'))

    def test_invalid_token_still_401(self):
        """Invalid token (not invalid issuer) should still return 401."""
        response = self.client.get('/protected', headers={
            'Authorization': 'Bearer notavalidtoken'
        })

        self.assertEqual(response.status_code, 401)
        response_text = response.get_data(as_text=True)
        self.assertTrue('Unauthorized' in response_text)


