import pytest
import json
from unittest.mock import patch, MagicMock
from utils.gql import GqlApi, GqlApiErrorForbiddenSchema

def test_single_forbidden_schema():
    """
    When a query triggers a single forbidden schema,
    the exception should contain a list with that schema.
    """
    # Mock the GraphQL client execute method
    with patch('graphqlclient.GraphQLClient.execute') as mock_execute:
        # First call: integrations query (skip_validation=True)
        mock_execute.side_effect = [
            json.dumps({
                'data': {
                    'integrations': [
                        {'name': 'my-integration', 'schemas': ['schema1', 'schema2']}
                    ]
                }
            }),
            json.dumps({
                'data': {},
                'extensions': {'schemas': ['schema3']}
            })
        ]
        api = GqlApi(url='http://example.com', int_name='my-integration', validate_schemas=True)
        with pytest.raises(GqlApiErrorForbiddenSchema) as exc_info:
            api.query('query { something }')
        # The exception should contain a list
        assert exc_info.value.args[0] == (
            "Forbidden schemas: ['schema3']\n\n"
            "The `schemas` parameter in the integration file in App-Interface\n"
            "should be updated to include these schemas."
        )

def test_multiple_forbidden_schemas():
    """
    When a query triggers multiple forbidden schemas,
    the exception should list all of them.
    """
    with patch('graphqlclient.GraphQLClient.execute') as mock_execute:
        mock_execute.side_effect = [
            json.dumps({
                'data': {
                    'integrations': [
                        {'name': 'my-integration', 'schemas': ['schema1', 'schema2']}
                    ]
                }
            }),
            json.dumps({
                'data': {},
                'extensions': {'schemas': ['schema2', 'schema3', 'schema4']}
            })
        ]
        api = GqlApi(url='http://example.com', int_name='my-integration', validate_schemas=True)
        with pytest.raises(GqlApiErrorForbiddenSchema) as exc_info:
            api.query('query { something }')
        # Forbidden schemas are schema3 and schema4 (schema2 is allowed)
        # The list order may be as they appear in query_schemas
        # The implementation uses list comprehension preserving order
        assert exc_info.value.args[0] == (
            "Forbidden schemas: ['schema3', 'schema4']\n\n"
            "The `schemas` parameter in the integration file in App-Interface\n"
            "should be updated to include these schemas."
        )

def test_no_forbidden_schemas():
    """
    When all schemas are allowed, no exception should be raised.
    """
    with patch('graphqlclient.GraphQLClient.execute') as mock_execute:
        mock_execute.side_effect = [
            json.dumps({
                'data': {
                    'integrations': [
                        {'name': 'my-integration', 'schemas': ['schema1', 'schema2', 'schema3']}
                    ]
                }
            }),
            json.dumps({
                'data': {'result': 'ok'},
                'extensions': {'schemas': ['schema1', 'schema2']}
            })
        ]
        api = GqlApi(url='http://example.com', int_name='my-integration', validate_schemas=True)
        result = api.query('query { something }')
        # query returns result['data']
        assert result == {'result': 'ok'}

def test_error_message_format():
    """
    Ensure the error message uses plural 'schemas' and lists the schemas as a Python list.
    """
    with patch('graphqlclient.GraphQLClient.execute') as mock_execute:
        mock_execute.side_effect = [
            json.dumps({
                'data': {
                    'integrations': [
                        {'name': 'my-integration', 'schemas': ['schema1']}
                    ]
                }
            }),
            json.dumps({
                'data': {},
                'extensions': {'schemas': ['schema2', 'schema3']}
            })
        ]
        api = GqlApi(url='http://example.com', int_name='my-integration', validate_schemas=True)
