                'id': 'RELEASE TRACK ID %d' % i,
                'recording': recording,
                'position': i,
                'number': 'A1',
            }
            if track_length:
                track['length'] = track_length
            if track_artist:
                track['artist-credit'] = [
                    {
                        'artist': {
                            'name': 'TRACK ARTIST NAME',
                            'id': 'TRACK ARTIST ID',
                            'sort-name': 'TRACK ARTIST SORT NAME',
                        },
                        'name': 'TRACK ARTIST CREDIT',
                    }
                ]
            track_list.append(track)
    release['medium-list'].append({
        'position': '1',
        'track-list': track_list,
        'format': 'FORMAT',
    })
    return release


