    with mock.patch('reconcile.github_org.gql.get_api', return_value=mock_gql), \
         mock.patch('reconcile.github_org.secret_reader.read', mock_secret_reader.read), \
         mock.patch('reconcile.github_org.queries', mock_queries):
        config = get_config(desired_org_name='app-sre')
        # Ensure secret_reader.read was called only once for app-sre token
        assert mock_secret_reader.read.call_count == 1
