import sys
from unittest import TestCase
from unittest.mock import patch, MagicMock
import pytest
from botocore.exceptions import ClientError

import reconcile.aws_support_cases_sos as integ


class TestAwsSupportCasesSosIntegration(TestCase):
    """
    Tests for the aws-support-cases-sos integration filtering.
    These tests must fail on the parent commit (where filter_accounts is not applied)
    and pass on the current commit.
    """

    @patch.object(integ, 'queries')
    @patch.object(integ, 'AWSApi')
    def test_only_premium_support_accounts_passed_to_awsapi(self, mock_aws_api, mock_queries):
        """
        Ensure that only accounts with premiumSupport=True are passed to AWSApi.
        """
        # Mock accounts returned by queries.get_aws_accounts
        premium_acc = {"name": "premium", "premiumSupport": True, "deleteKeys": []}
        non_premium_acc = {"name": "nonpremium", "premiumSupport": False, "deleteKeys": []}
        no_flag_acc = {"name": "noflag", "deleteKeys": []}
        mock_queries.get_aws_accounts.return_value = [premium_acc, non_premium_acc, no_flag_acc]
        mock_queries.get_app_interface_settings.return_value = {}

        # Mock AWSApi instance methods
        mock_aws_instance = MagicMock()
        mock_aws_instance.get_support_cases.return_value = {}
        mock_aws_instance.get_users_keys.return_value = {}
        mock_aws_api.return_value = mock_aws_instance

        # Run the integration
        integ.run(dry_run=True, gitlab_project_id=None)

        # Verify AWSApi was instantiated with only the premium account
        # The filter_accounts function should have filtered out non-premium and noflag.
        mock_aws_api.assert_called_once()
        call_args = mock_aws_api.call_args
        # AWSApi is called with (thread_pool_size, accounts, settings=settings)
        # We care about the accounts argument (index 1)
        passed_accounts = call_args[0][1]
        self.assertEqual(passed_accounts, [premium_acc])

    @patch.object(integ, 'queries')
    @patch.object(integ, 'AWSApi')
    def test_no_premium_support_accounts(self, mock_aws_api, mock_queries):
        """
        When no accounts have premiumSupport, AWSApi should receive an empty list.
        """
        mock_queries.get_aws_accounts.return_value = [
            {"name": "acc1", "premiumSupport": False, "deleteKeys": []},
            {"name": "acc2", "premiumSupport": None, "deleteKeys": []},
            {"name": "acc3", "deleteKeys": []},
        ]
        mock_queries.get_app_interface_settings.return_value = {}

        mock_aws_instance = MagicMock()
        mock_aws_instance.get_support_cases.return_value = {}
        mock_aws_instance.get_users_keys.return_value = {}
        mock_aws_api.return_value = mock_aws_instance

        integ.run(dry_run=True, gitlab_project_id=None)

        mock_aws_api.assert_called_once()
        passed_accounts = mock_aws_api.call_args[0][1]
        self.assertEqual(passed_accounts, [])

    @patch.object(integ, 'queries')
    @patch.object(integ, 'AWSApi')
    def test_integration_skips_non_premium_accounts(self, mock_aws_api, mock_queries):
        """
        The integration should skip accounts without premium support,
        preventing SubscriptionRequiredException.
        """
        premium_acc = {"name": "premium", "premiumSupport": True, "deleteKeys": []}
        non_premium_acc = {"name": "nonpremium", "premiumSupport": False, "deleteKeys": []}
        mock_queries.get_aws_accounts.return_value = [premium_acc, non_premium_acc]
        mock_queries.get_app_interface_settings.return_value = {}

        # Create a mock AWSApi instance that raises ClientError for non-premium accounts
        # if they are passed to get_support_cases.
        mock_aws_instance = MagicMock()
        # We'll simulate that get_support_cases returns empty dict for premium account
        # and raises for non-premium. However, because the integration filters accounts,
        # non-premium should not be passed to AWSApi at all.
        # We'll set get_support_cases to return empty dict (since only premium account is passed).
        mock_aws_instance.get_support_cases.return_value = {}
        mock_aws_instance.get_users_keys.return_value = {}
        mock_aws_api.return_value = mock_aws_instance

        # This should not raise any exception
        integ.run(dry_run=True, gitlab_project_id=None)

        # Verify that get_support_cases was called (once, with filtered accounts)
        mock_aws_instance.get_support_cases.assert_called_once()

    @patch.object(integ, 'queries')
    @patch.object(integ, 'AWSApi')
    def test_integration_handles_subscription_required_exception(self, mock_aws_api, mock_queries):
        """
        Simulate that AWS Support API would raise SubscriptionRequiredException for non-premium accounts.
        The integration should not crash because those accounts are filtered out.
        """
        premium_acc = {"name": "premium", "premiumSupport": True, "deleteKeys": []}
        non_premium_acc = {"name": "nonpremium", "premiumSupport": False, "deleteKeys": []}
        mock_queries.get_aws_accounts.return_value = [premium_acc, non_premium_acc]
        mock_queries.get_app_interface_settings.return_value = {}

        # Mock AWSApi to raise ClientError with SubscriptionRequiredException for non-premium accounts.
        # We'll need to inspect which accounts are passed to AWSApi constructor.
        # We'll capture the accounts passed to AWSApi and then have get_support_cases raise for those without premium.
        captured_accounts = []
        def awsapi_side_effect(thread_pool_size, accounts, settings):
            captured_accounts.extend(accounts)
            mock_instance = MagicMock()
            # If any account in accounts is non-premium, we could raise, but we want to test that they are filtered.
            # Instead, we'll just set return values.
            mock_instance.get_support_cases.return_value = {}
            mock_instance.get_users_keys.return_value = {}
            return mock_instance
        mock_aws_api.side_effect = awsapi_side_effect

        # Run integration
        integ.run(dry_run=True, gitlab_project_id=None)

        # Verify that only premium account is in captured_accounts
        self.assertEqual(len(captured_accounts), 1)
        self.assertEqual(captured_accounts[0]["name"], "premium")


